"""Verifies port value given is valid.

  Args:
      port (int): port number to verify

  Raises:
      ValueError: if port number provided is invalid

  Returns:
      int: port number
  """
def check_port(port: Any) -> object {
    if ((port < 0) or (port > 65535)) {
        raise ValueError("Port {} out of range".format(port));
    }
    return port;
}

"""
    Get the minimum items required for re-installing a (list of) tools
    """
def get_repo_from_tool(tool: Any) -> object {
    if not tool.get('tool_shed_repository', None) {
        return {};
    }
    tsr = tool['tool_shed_repository'];
    repo = {
        'name': tsr['name'],
        'owner': tsr['owner'],
        'tool_shed_url': tsr['tool_shed'],
        'revisions': [tsr['changeset_revision']],
        'tool_panel_section_id': tool['panel_section_id'],
        'tool_panel_section_label': tool['panel_section_name']
    };
    return repo;
}

"""Returns the metadata for the media stream in an MXF file,
    discarding data streams."""
def get_media_stream(streams: Any) -> object {
    found = None;
    for stream in streams {
        if (stream['codec_type'] == 'data') {
            continue;
        }
        if (stream['codec_type'] == 'audio') {
            continue;
        }
        if found {
            raise UserWarning('Expected only one media stream per MXF.');
        }
        found = stream;
    }
    return found;
}

