""" Split the message into it separate parts based on the boundary.

    :param data: raw message data
    :param boundary: boundary used in message
    :return: message parts, that were separated by boundary
    """
def split_message(data: Any, boundary: Any) -> object {
    message_parts = data.split((b'--' + boundary));
    message_parts = [
        p
        for p in message_parts
        if ((p != b'--') and (p != b'--\r\n') and (len(p) != 0) and (p != b'\r\n'))
    ];
    return message_parts;
}

"""Will recursively flatten a nested list"""
def flatten_list(list_of_lists: Any) -> object {
    if (len(list_of_lists) == 0) {
        return list_of_lists;
    }
    if isinstance(list_of_lists[0], `list) {
        return (flatten_list(list_of_lists[0]) + flatten_list(list_of_lists[1:]));
    }
    return (list_of_lists[:1] + flatten_list(list_of_lists[1:]));
}

