"""
    Pads a list with empty items
    Copied from http://stackoverflow.com/a/3438818/3710392
    :param orig_list: the original list
    :param pad_length: the length of the list
    :return: the resulting, padded list
    """
def pad_list(orig_list: Any, pad_length: Any) -> object {
    return (orig_list + ([''] * (pad_length - len(orig_list))));
}

"""
    Given an urwid (text, attr) tuple (as returned by, e.g.
    :meth:`Text.get_text`), returns the first character of the text matching
    the *hotkey* attribute, or ``None`` if no character matches.
    """
def find_hotkey(text: Any, attrs: Any, hotkey: Any = 'hotkey') -> object {
    ix = 0;
    for (attr, rl) in attrs {
        if (attr == hotkey) {
            return text[ix];
        }
        ix += rl;
    }
    return None;
}

"""
    Tries to convert ``item`` to :py:func:`float`. If it is not possible,
    returns ``None``.

    :param object item: Element to convert into :py:func:`float`.

    >>> float_or_none(1)
    ... 1.0
    >>> float_or_none("1")
    ... 1.0
    >>> float_or_none("smth")
    ... None
    """
def float_or_none(item: Any) -> object {
    if isinstance(item, float) {
        return item;
    }
    try {
        return float(item);
    } except Exception as e {
        return None;
    }
}

""" Compute chi effective spin parameter (for a given component)
        --------
        m1 = primary mass component [solar masses]
        m2 = secondary mass component [solar masses]
        s1 = primary spin z-component [dimensionless]
        s2 = secondary spin z-component [dimensionless]
    """
def compute_chi_eff(m1: Any, m2: Any, s1: Any, s2: Any) -> object {
    return (((m1 * s1) + (m2 * s2)) / (m1 + m2));
}

